import { fileURLToPath } from "node:url";
import manifest from "./manifest.json" with { type: "json" };

export default {
  root: fileURLToPath(new URL(".", import.meta.url)),
  publicDir: false,
  oxc: { jsx: { runtime: "classic" } },
  build: {
    lib: {
      entry: "src/index.jsx",
      formats: ["es"],
      fileName: () => "plugin.js",
    },
    rolldownOptions: {
      output: {
        codeSplitting: false,
        banner:
          "// biome-ignore-all lint: Generated bundle; lint the source instead.\n// biome-ignore-all format: Generated by vite.config.mjs.",
      },
    },
  },
  plugins: [
    {
      name: "plugin-contract",
      enforce: "pre",
      resolveId(id) {
        if (
          /^react(?:-dom)?(?:\/|$)/.test(id) ||
          id.startsWith("@deepseek-ai/cordis") ||
          id === "@buzz/author"
        )
          throw new Error(
            "Use injected host capabilities, not runtime imports.",
          );
      },
      generateBundle(_options, bundle) {
        const files = Object.values(bundle);
        if (
          files.length !== 1 ||
          files[0].type !== "chunk" ||
          files[0].imports.length ||
          files[0].dynamicImports.length
        )
          throw new Error("The plugin must be a single self-contained module.");
        files[0].code = files[0].code.replace(/[ \t]+$/gm, "");
        this.emitFile({
          type: "asset",
          fileName: "manifest.json",
          source: `${JSON.stringify(manifest, null, 2)}\n`,
        });
      },
    },
  ],
};
